SELECT ?s ?label ?class {
  ?s ref:label ?label .
  ?s a ?class .
  FILTER(CONTAINS(?label,"ZN_") || CONTAINS(?label,"Zone"))
} LIMIT 50

SELECT ?z ?label {
  ?z a ?c .
  ?z rdfs:label ?label .
  FILTER(CONTAINS(?label,"top_ZN_2") || CONTAINS(?label,"DataCenter_bot_ZN_6"))
} LIMIT 40

SELECT ?p ?label ?class ?ts {
  ?p rdfs:label ?label .
  ?p brick:isPointOf ?z .
  ?z rdfs:label ?zlabel .
  OPTIONAL {?p ref:hasTimeseriesId ?ts}
  FILTER(CONTAINS(?zlabel,"top_ZN_2") || CONTAINS(?zlabel,"DataCenter_bot_ZN_6"))
}

SELECT ?p ?label ?class ?z ?zlabel ?ts {
  ?p brick:isPointOf ?z .
  ?p rdfs:label ?label .
  ?z rdfs:label ?zlabel .
  OPTIONAL {?p ref:hasTimeseriesId ?ts}
  FILTER(CONTAINS(?zlabel,"Perimeter_top_ZN_2"))
}

SELECT ?p ?label ?class ?ts {
  ?p brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z03> .
  ?p rdfs:label ?label .
  ?p a ?class .
  OPTIONAL {?p ref:hasTimeseriesId ?ts}
}

SELECT ?p ?ts ?er {
  ?p brick:isPointOf ?z .
  FILTER(?z = <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z03> || ?z = <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z07>)
  OPTIONAL {?p ref:hasTimeseriesId ?ts . ?p ref:hasExternalReference ?er}
  FILTER(CONTAINS(str(?p),"Zone_Air_Temperature_Sensor"))
}

